 */

/** cooking技能 → 自己做饭折扣（技能越高做饭越划算） */
function getCookingDiscount(cookingLevel) {
  // 自己做饭花费 = 基础花费 * (1 - cookingLevel * 0.008)
  // level 0: 全额, level 50: 6折, level 100: 2折（最低保底3折）
