  sk.xp = (sk.xp || 0) + xpGain;

  // 检查升级
  var leveledUp = false;
  while (sk.xp >= (sk.level + 1) * 120 && sk.level < 100) {
    sk.xp -= (sk.level + 1) * 120;
    sk.level++;
    leveledUp = true;
    // 升级提升关联属性（微量）
    applySkillLevelUpBonus(entry.skill, state);
  }

