81	// ====== 欢迎界面 ======
82	function showWelcome() {
83	  document.getElementById("app").style.display = "none";
84	  const welcome = document.getElementById("welcome-screen");
85	  welcome.style.display = "flex";
86	
87	  // 更新继续游戏按钮区域
88	  const loadSection = document.getElementById("load-section");
