209	// ====== 可用行动列表 ======
210	function getAvailableActions(state) {
211	  const actions = [];
212	
213	  // 提升为函数级变量（用 let，块内可重新指向用 const）
214	  const locKey = state.trade.currentLocation;
215	
216	  if (state.player.phase === "street") {
217	    // --- 街头阶段行动 ---
218	
219	    // 1. 工作
220	    const jobIds = getJobsAtLocation(locKey);
221	    for (const jobId of jobIds) {
222	      const job = getJobById(jobId);
223	      if (!job) continue;
224	      const reqFail = checkJobRequirements(job, state);
225	      const payEstimate = reqFail ? null : estimateJobPay(job, state);
226	
227	      // 摆摊类工作添加客流量提示
228	      const isVending = [
229	        "street_vending_food",
230	        "street_vending_goods",
231	        "food_stall",
232	      ].includes(jobId);
233	      let footfallLabel = "";
234	      if (
235	        isVending &&
236	        typeof getVendingFootfallMod === "function" &&
237	        typeof getFootfallStars === "function"
238	      ) {
239	        const mod = getVendingFootfallMod(locKey, state);
240	        footfallLabel = " | " + getFootfallStars(mod);
241	      }
242	
243	      actions.push({
244	        id: "job_" + jobId,
245	        name: job.name,
246	        desc: job.desc + footfallLabel,
247	        icon: job.icon,
248	        payEstimate: payEstimate
249	          ? `${payEstimate - (job.startupCost || 0)}~${payEstimate + Math.floor(payEstimate * 0.3)}`
250	          : null,
251	        costEstimate: job.startupCost || null,
252	        reqFail,
253	        disabled:
254	          !!reqFail ||
255	          (job.startupCost && state.resources.cash < job.startupCost
256	            ? `启动资金不足(需¥${job.startupCost})`
257	            : null) ||
258	          null,
259	        handler: () => {
260	          const finalReq = checkJobRequirements(job, state);
261	          if (finalReq) {
262	            StateManager.addMessage(`⚠️ ${finalReq}`, "warning");
263	            return;
264	          }
265	          if (job.startupCost && state.resources.cash < job.startupCost) {
266	            StateManager.addMessage(
267	              `⚠️ 启动资金不足，需要 ¥${job.startupCost}`,
268	              "warning",
269	            );
270	            return;
271	          }
272	          doStreetJob(job);
273	        },
274	      });
275	    }
276	
277	    // 如果没有可用工作
278	    if (jobIds.length === 0) {
279	      actions.push({
280	        id: "no_jobs",
281	        name: "当前地点没有工作机会",
282	        desc: "尝试旅行到其他地点寻找工作。",
283	        icon: "🚫",
284	        disabled: true,
285	      });
286	    }
287	
288	    // 批发市场 — 批发进货
289	    if (locKey === "wholesaleMarket") {
290	      actions.push({
291	        id: "wholesale_header",
292	        name: "📦 批发进货（转到交易Tab）",
293	        desc: "在批发市场以折扣价批量购入商品，转手到商业区卖出赚差价！",
294	        icon: "📦",
295	        handler: () => {
296	          switchTab("trade");
297	        },
298	      });
299	    }
300	
301	    // 零售买卖 — 在任何有价格数据的地点都可以买卖
302	    if (
303	      state.trade.goodsPrices[locKey] &&
304	      Object.keys(state.trade.goodsPrices[locKey]).length > 0
305	    ) {
306	      actions.push({
307	        id: "trade_header",
308	        name: "🛒 买卖商品（转到交易Tab）",
309	        desc: "查看当前市场价格，低买高卖赚取差价。",
310	        icon: "🛒",
311	        handler: () => {
312	          switchTab("trade");
313	        },
314	      });
315	    }
316	
317	    // === 住所系统 ===
318	    if (locKey === "slum") {
319	      const currentTier = state.housing?.tier || 0;
320	      // HOUSING_TIERS 定义在 data/items.js 中（全局常量）
321	
322	      // 显示当前住所
323	      const curHouse = HOUSING_TIERS[currentTier];
324	      actions.push({
325	        id: "housing_current",
326	        name: `${curHouse.icon} 当前住所：${curHouse.name}`,
327	        desc: `容量+${curHouse.capacity} | 睡眠恢复疲劳-${curHouse.fatigueRecovery} | ${curHouse.desc}${curHouse.rent > 0 ? ` | 日租¥${curHouse.rent}/天` : ""}`,
328	        icon: curHouse.icon,
329	        disabled: true,
330	      });
331	
332	      // 可升级的住所
333	      for (let t = currentTier + 1; t < HOUSING_TIERS.length; t++) {
334	        const house = HOUSING_TIERS[t];
335	        const canAfford = state.resources.cash >= house.cost;
336	        actions.push({
337	          id: "housing_upgrade_" + t,
338	          name: `⬆️ 升级到${house.name}`,
339	          desc: `${house.desc} 一次性付¥${house.cost} + 日租¥${house.rent}/天`,
340	          icon: house.icon,
341	          costEstimate: house.cost,
342	          disabled: !canAfford,
343	          reqFail: !canAfford ? `需 ¥${house.cost}` : null,
344	          handler: () => {
345	            state.resources.cash -= house.cost;
346	            state.housing.tier = t;
347	            state.housing.rentedDay = state.player.day;
348	            state.inventory.capacity =
349	              house.capacity + (state.housing.storageCapacity || 0);
350	            StateManager.addMessage(
351	              `🏠 搬进了${house.name}！容量提升至${state.inventory.capacity}。`,
352	              "success",
353	            );
354	          },
355	        });
356	      }
357	    }
358	
359	    // === 仓库租赁（批发市场）===
360	    if (locKey === "wholesaleMarket") {
361	      const hasStorage = state.housing?.storageRented;
362	      const STORAGE_OPTIONS = [
363	        {
364	          id: "small",
365	          name: "小仓库",
366	          cost: 500,
367	          rent: 20,
368	          capacity: 150,
369	          icon: "📦",
370	        },
371	        {
372	          id: "big",
373	          name: "大仓库",
374	          cost: 1500,
375	          rent: 50,
376	          capacity: 500,
377	          icon: "🏗️",
378	        },
379	      ];
380	
381	      if (hasStorage) {
382	        actions.push({
383	          id: "storage_current",
384	          name: `📦 已租仓库 (额外+${state.housing.storageCapacity || 0}容量)`,
385	          desc: `日租¥${STORAGE_OPTIONS.find((s) => s.capacity === state.housing.storageCapacity)?.rent || "?"}/天`,
386	          icon: "📦",
387	          disabled: true,
388	        });
389	      } else {
390	        for (const opt of STORAGE_OPTIONS) {
391	          const canAfford = state.resources.cash >= opt.cost;
392	          actions.push({
393	            id: "storage_rent_" + opt.id,
394	            name: `📦 租用${opt.name}`,
395	            desc: `额外+${opt.capacity}商品存储容量。一次性¥${opt.cost} + 日租¥${opt.rent}/天`,
396	            icon: opt.icon,
397	            costEstimate: opt.cost,
398	            disabled: !canAfford,
399	            reqFail: !canAfford ? `需 ¥${opt.cost}` : null,
400	            handler: () => {
401	              state.resources.cash -= opt.cost;
402	              state.housing.storageRented = true;
403	              state.housing.storageCapacity = opt.capacity;
404	              const baseCap = [20, 50, 100, 200][state.housing.tier || 0];
405	              state.inventory.capacity = baseCap + opt.capacity;
406	              StateManager.addMessage(
407	                `📦 租下了${opt.name}！总容量提升至${state.inventory.capacity}。`,
408	                "success",
409	              );
410	            },
411	          });
412	        }
413	      }
414	    }
415	
416	    // === 背包升级（商业区）===
417	    if (locKey === "commercialDist") {
418	      const BACKPACKS = [
419	        {
