922	function doStreetJob(job) {
923	  const state = StateManager.getState();
924	
925	  // 扣除启动资金
926	  if (job.startupCost) {
927	    state.resources.cash -= job.startupCost;
928	  }
929	
930	  // 计算收入（含新闻+情绪修正）
931	  let pay = job.payCalc(state);
932	  if (state._jobMultipliers && state._jobMultipliers[job.id]) {
933	    pay = Math.floor(pay * state._jobMultipliers[job.id]);
934	  }
935	  if (state._allJobsBonus && state._allJobsBonus !== 1) {
936	    pay = Math.floor(pay * state._allJobsBonus);
937	  }
938	  const emoMod =
939	    typeof getEmotionWorkModifier === "function"
940	      ? getEmotionWorkModifier(state)
941	      : null;
942	  if (emoMod) {
943	    pay = Math.floor(pay * (emoMod.pay || 1));
944	  }
945	  // ===技能加权收入：减少纯RNG依赖，技能越高中位收入越高 ===
946	  const skillBonus = getSkillPayBonus(job.id, state);
947	  if (skillBonus > 1.0) {
948	    pay = Math.floor(pay * skillBonus);
949	  }
950	  // 新人保护：前15天废品回收+5，苦力类+3
951	  if (state.player.day <= 15) {
952	    const boostedJobs = [
953	      "waste_recycling",
954	      "manual_labor_construction",
955	      "warehouse_worker",
956	      "factory_work_assembly",
957	    ];
958	    if (boostedJobs.includes(job.id)) {
959	      const newbieBonus = job.id === "waste_recycling" ? 2 : 2;
960	      pay += newbieBonus;
961	    }
962	  }
963	  state.resources.cash += pay;
964	  state.resources.totalEarned += pay;
965	  state.employment.completedShifts[job.id] =
966	    (state.employment.completedShifts[job.id] || 0) + 1;
967	
968	  // 应用效果
969	  if (job.effects) {
970	    if (job.effects.fatigue)
971	      state.needs.fatigue = Math.min(
972	        100,
973	        state.needs.fatigue + job.effects.fatigue,
974	      );
975	    if (job.effects.hygiene)
976	      state.needs.hygiene = Math.max(
977	        0,
978	        Math.min(100, state.needs.hygiene + job.effects.hygiene),
979	      );
980	    if (job.effects.happiness)
981	      state.needs.happiness = Math.max(
982	        0,
